    // --- build_report edge cases ---

    #[test]
    fn build_report_with_none_exit_code() {
        let report = build_report(
            "test",
            "make build",
            None,
            "error output",
            "fix",
            &HashMap::new(),
        );
        assert_eq!(report.exit_code, None);
    }

    #[test]
    fn build_report_scrubs_secrets_in_command() {
        let mut env = HashMap::new();
        env.insert("API_KEY".to_string(), "secret123".to_string());

        let report = build_report(
            "deploy",
            "curl -H secret123 https://example.com",
            Some(1),
            "",
            "retry",
            &env,
        );
        assert!(!report.command_scrubbed.contains("secret123"));
    }

    #[test]
    fn build_report_scrubs_paths_in_error() {
        let report = build_report(
            "build",
            "cargo build",
            Some(1),
            "Error at /home/user/project/src/lib.rs:10",
            "retry",
            &HashMap::new(),
        );
        assert!(!report.error_scrubbed.contains("/home/user"));
        assert!(report.error_scrubbed.contains("[PATH]"));
    }

    #[test]
    fn build_report_platform_is_os_arch() {
        let report = build_report(
            "test",
            "echo test",
            Some(0),
            "",
            "retry",
            &HashMap::new(),
        );
        let expected = format!("{}-{}", std::env::consts::OS, std::env::consts::ARCH);
        assert_eq!(report.platform, expected);
    }

    // --- prompt_telemetry edge cases ---

    #[test]
    fn telemetry_prompt_returns_always_from_ui() {
        let report = build_report("test", "echo test", Some(0), "", "retry", &HashMap::new());
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("telemetry_failure", "always");

        let result = prompt_telemetry(&mut ui, &report, None).unwrap();
        assert_eq!(result, TelemetryConsent::Always);
    }

    #[test]
    fn telemetry_prompt_returns_never_from_ui() {
        let report = build_report("test", "echo test", Some(0), "", "retry", &HashMap::new());
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("telemetry_failure", "never");

        let result = prompt_telemetry(&mut ui, &report, None).unwrap();
        assert_eq!(result, TelemetryConsent::Never);
    }

    #[test]
    fn telemetry_prompt_unknown_saved_pref_still_prompts() {
        let report = build_report("test", "echo test", Some(0), "", "retry", &HashMap::new());
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("telemetry_failure", "send");

        let result = prompt_telemetry(&mut ui, &report, Some("garbage")).unwrap();
        assert_eq!(result, TelemetryConsent::Send);
        assert_eq!(ui.prompts_shown().len(), 1);
    }

    #[test]
    fn telemetry_prompt_displays_step_name() {
        let report = build_report(
            "bundler",
            "bundle install",
            Some(1),
            "gem error",
            "shell → retry",
            &HashMap::new(),
        );
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("telemetry_failure", "no_thanks");

        prompt_telemetry(&mut ui, &report, None).unwrap();

        assert!(ui.has_message("bundler"));
        assert!(ui.has_message("bundle install"));
        assert!(ui.has_message("Exit:    1"));
        assert!(ui.has_message("gem error"));
        assert!(ui.has_message("shell → retry"));
    }

    #[test]
    fn telemetry_prompt_omits_exit_code_when_none() {
        let report = build_report(
            "test",
            "echo test",
            None,
            "some error",
            "retry",
            &HashMap::new(),
        );
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("telemetry_failure", "no_thanks");

        prompt_telemetry(&mut ui, &report, None).unwrap();

        let exit_messages: Vec<_> = ui
            .messages()
            .iter()
            .filter(|m| m.contains("Exit:"))
            .collect();
        assert!(exit_messages.is_empty());
    }

    #[test]
    fn telemetry_prompt_omits_error_when_empty() {
        let report = build_report("test", "echo test", Some(0), "", "retry", &HashMap::new());
        let mut ui = crate::ui::MockUI::new();
