input.new_string:
    #[test]
    fn scrub_removes_home_paths() {
        let input = "Error at /home/user/project/file.rs:42";
        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
        assert!(scrubbed.contains("[PATH]"));
        assert!(!scrubbed.contains("/home/user"));
    }

    // --- TelemetryConsent Display ---

    #[test]
    fn consent_display_send() {
        assert_eq!(TelemetryConsent::Send.to_string(), "send");
    }

    #[test]
    fn consent_display_no_thanks() {
        assert_eq!(TelemetryConsent::NoThanks.to_string(), "no_thanks");
    }

    #[test]
    fn consent_display_always() {
        assert_eq!(TelemetryConsent::Always.to_string(), "always");
    }

    #[test]
    fn consent_display_never() {
        assert_eq!(TelemetryConsent::Never.to_string(), "never");
    }

    // --- scrub_for_telemetry edge cases ---

    #[test]
    fn scrub_empty_input_returns_empty() {
        let scrubbed = scrub_for_telemetry("", &HashMap::new());
        assert_eq!(scrubbed, "");
    }

    #[test]
    fn scrub_combined_secrets_paths_and_tokens() {
        let mut env = HashMap::new();
        env.insert("DB_PASSWORD".to_string(), "hunter2".to_string());

        let input = "Error: hunter2 at /Users/dev/app ghp_abcdefghijklmnopqrstuvwxyz1234567890";
        let scrubbed = scrub_for_telemetry(input, &env);

        assert!(!scrubbed.contains("hunter2"));
        assert!(!scrubbed.contains("/Users/dev"));
        assert!(!scrubbed.contains("ghp_"));
        assert!(scrubbed.contains("[PATH]"));
        assert!(scrubbed.contains("[REDACTED]"));
    }

    #[test]
    fn scrub_removes_windows_paths() {
        let input = r"Error at C:\Users\brenna\project\src\main.rs";
        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
        assert!(scrubbed.contains("[PATH]"));
        assert!(!scrubbed.contains(r"C:\Users\brenna"));
    }

    #[test]
    fn scrub_removes_tmp_paths() {
        let input = "Error at /tmp/build-abc123/output.log";
        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
        assert!(scrubbed.contains("[PATH]"));
        assert!(!scrubbed.contains("/tmp/build"));
    }

    #[test]
    fn scrub_removes_slack_xoxb_tokens() {
        let input = "token: xoxb-123456789-abcdefghij";
        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
        assert!(scrubbed.contains("[REDACTED]"));
        assert!(!scrubbed.contains("xoxb-"));
    }

    #[test]
    fn scrub_removes_slack_xoxp_tokens() {
        let input = "token: xoxp-123456789-abcdefghij";
        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
        assert!(scrubbed.contains("[REDACTED]"));
        assert!(!scrubbed.contains("xoxp-"));
    }

    #[test]
    fn scrub_removes_gho_tokens() {
        let input = "token: gho_abcdefghijklmnopqrstuvwxyz1234567890";
        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
        assert!(scrubbed.contains("[REDACTED]"));
        assert!(!scrubbed.contains("gho_"));
    }

    #[test]
    fn scrub_removes_long_hex_strings() {
        let input = "hash: abcdef0123456789abcdef0123456789";
        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
        assert!(scrubbed.contains("[REDACTED]"));
        assert!(!scrubbed.contains("abcdef0123456789abcdef0123456789"));
    }

    #[test]
    fn scrub_ignores_non_secret_env_vars() {
        let mut env = HashMap::new();
        env.insert("PATH".to_string(), "/usr/local/bin".to_string());
        env.insert("HOME".to_string(), "/Users/dev".to_string());

        let input = "safe text only";
        let scrubbed = scrub_for_telemetry(input, &env);
        assert_eq!(scrubbed, "safe text only");
    }

    #[test]
    fn scrub_skips_empty_secret_values() {
        let mut env = HashMap::new();
        env.insert("API_KEY".to_string(), "".to_string());

        let input = "no crash here";
        let scrubbed = scrub_for_telemetry(input, &env);
        assert_eq!(scrubbed, "no crash here");
    }

    #[test]
    fn scrub_truncation_at_exact_boundary() {
        let input = "x".repeat(MAX_ERROR_LENGTH);
        let scrubbed = scrub_for_telemetry(&input, &HashMap::new());
        assert_eq!(scrubbed.len(), MAX_ERROR_LENGTH);
        assert!(!scrubbed.ends_with("...[truncated]"));
    }

    #[test]
    fn scrub_truncation_one_over_boundary() {
        let input = "x".repeat(MAX_ERROR_LENGTH + 1);
        let scrubbed = scrub_for_telemetry(&input, &HashMap::new());
        assert!(scrubbed.ends_with("...[truncated]"));
    }

    // --- build_report edge cases ---

    #[test]
    fn build_report_with_none_exit_code() {
        let report = build_report(
            "test",
            "make build",
            None,
            "error output",
            "fix",
            &HashMap::new(),
        );
        assert_eq!(report.exit_code, None);
    }

    #[test]
    fn build_report_scrubs_secrets_in_command() {
        let mut env = HashMap::new();
        env.insert("API_KEY".to_string(), "secret123".to_string());

        let report = build_report(
            "deploy",
            "curl -H secret123 https://example.com",
            Some(1),
            "",
            "retry",
            &env,
        );
        assert!(!report.command_scrubbed.contains("secret123"));
    }

    #[test]
    fn build_report_scrubs_paths_in_error() {
        let report = build_report(
            "build",
            "cargo build",
            Some(1),
            "Error at /home/user/project/src/lib.rs:10",
            "retry",
            &HashMap::new(),
        );
        assert!(!report.error_scrubbed.contains("/home/user"));
        assert!(report.error_scrubbed.contains("[PATH]"));
    }

    #[test]
    fn build_report_platform_is_os_arch() {
        let report = build_report(
            "test",
            "echo test",
            Some(0),
            "",
            "retry",
            &HashMap::new(),
        );
        let expected = format!("{}-{}", std::env::consts::OS, std::env::consts::ARCH);
        assert_eq!(report.platform, expected);
    }

    // --- prompt_telemetry edge cases ---

    #[test]
    fn telemetry_prompt_returns_always_from_ui() {
        let report = build_report("test", "echo test", Some(0), "", "retry", &HashMap::new());
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("telemetry_failure", "always");

        let result = prompt_telemetry(&mut ui, &report, None).unwrap();
        assert_eq!(result, TelemetryConsent::Always);
    }

    #[test]
    fn telemetry_prompt_returns_never_from_ui() {
        let report = build_report("test", "echo test", Some(0), "", "retry", &HashMap::new());
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("telemetry_failure", "never");

        let result = prompt_telemetry(&mut ui, &report, None).unwrap();
        assert_eq!(result, TelemetryConsent::Never);
    }

    #[test]
    fn telemetry_prompt_unknown_saved_pref_still_prompts() {
        let report = build_report("test", "echo test", Some(0), "", "retry", &HashMap::new());
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("telemetry_failure", "send");

        let result = prompt_telemetry(&mut ui, &report, Some("garbage")).unwrap();
        assert_eq!(result, TelemetryConsent::Send);
        assert_eq!(ui.prompts_shown().len(), 1);
    }

    #[test]
    fn telemetry_prompt_displays_step_name() {
        let report = build_report(
            "bundler",
            "bundle install",
            Some(1),
            "gem error",
            "shell → retry",
            &HashMap::new(),
        );
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("telemetry_failure", "no_thanks");

        prompt_telemetry(&mut ui, &report, None).unwrap();

        assert!(ui.has_message("bundler"));
        assert!(ui.has_message("bundle install"));
        assert!(ui.has_message("Exit:    1"));
        assert!(ui.has_message("gem error"));
        assert!(ui.has_message("shell → retry"));
    }

    #[test]
    fn telemetry_prompt_omits_exit_code_when_none() {
        let report = build_report(
            "test",
            "echo test",
            None,
            "some error",
            "retry",
            &HashMap::new(),
        );
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("telemetry_failure", "no_thanks");

        prompt_telemetry(&mut ui, &report, None).unwrap();

        let exit_messages: Vec<_> = ui
            .messages()
            .iter()
            .filter(|m| m.contains("Exit:"))
            .collect();
        assert!(exit_messages.is_empty());
    }

    #[test]
    fn telemetry_prompt_omits_error_when_empty() {
        let report = build_report("test", "echo test", Some(0), "", "retry", &HashMap::new());
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("telemetry_failure", "no_thanks");

        prompt_telemetry(&mut ui, &report, None).unwrap();

        let error_messages: Vec<_> = ui
            .messages()
            .iter()
            .filter(|m| m.contains("Error:"))
            .collect();
        assert!(error_messages.is_empty());
    }

    #[test]
    fn telemetry_prompt_defaults_to_no_thanks() {
        let report = build_report("test", "echo test", Some(0), "", "retry", &HashMap::new());
        let mut ui = crate::ui::MockUI::new();

        let result = prompt_telemetry(&mut ui, &report, None).unwrap();
        assert_eq!(result, TelemetryConsent::NoThanks);
    }

    // --- reports_dir ---

    #[test]
    fn reports_dir_ends_with_failure_reports() {
        let dir = reports_dir();
        assert!(dir.ends_with("failure-reports"));
        assert!(dir.to_string_lossy().contains(".bivvy"));
    }

    // --- save_report_to ---

    #[test]
    fn save_report_creates_directory_if_missing() {
        let temp = tempfile::TempDir::new().unwrap();
        let nested = temp.path().join("deep").join("nested");

        let report = build_report("test", "echo", Some(0), "", "retry", &HashMap::new());
        let path = save_report_to(&report, &nested).unwrap();

        assert!(nested.exists());
        assert!(path.exists());
    }

    #[test]
    fn save_report_filename_contains_step_name() {
        let temp = tempfile::TempDir::new().unwrap();
        let report = build_report("bundler", "bundle install", Some(1), "", "retry", &HashMap::new());

        let path = save_report_to(&report, temp.path()).unwrap();
        let filename = path.file_name().unwrap().to_string_lossy();

        assert!(filename.contains("bundler"));
        assert!(filename.ends_with(".yml"));
    }

    #[test]
    fn save_report_filename_contains_timestamp_pattern() {
        let temp = tempfile::TempDir::new().unwrap();
        let report = build_report("test", "echo", Some(0), "", "retry", &HashMap::new());

        let path = save_report_to(&report, temp.path()).unwrap();
        let filename = path.file_name().unwrap().to_string_lossy();

